//! Zevui Components CLI — the installer, conflict checks and lock writer are Zig.
//! npm/bun are optional launchers only. Zig 0.17.1, no DVUI runtime in CLI.
const std = @import("std");
const Io = std.Io;
const Allocator = std.mem.Allocator;
const cwd = Io.Dir.cwd();
// Generated by scripts/build-registry.mjs; the mirror must stay inside the
// Zig root module directory so zig run and zig build can both embed it.
const registry_json = @embedFile("registry-bundle.json");
const config_name = "zevui.components.json";
const lock_name = ".zevui/components.lock.json";
const max_file_size = 1024 * 1024;

const SourceFile = struct {
    target: []const u8,
    content: []const u8,
    sha256: []const u8,
};
const RegistryItem = struct {
    name: []const u8,
    title: []const u8,
    files: []const SourceFile,
    registryDependencies: []const []const u8 = &.{},
};
const Registry = struct { items: []const RegistryItem };
const Options = struct {
    command: []const u8 = "help",
    project: []const u8 = ".",
    names: [64][]const u8 = undefined,
    count: usize = 0,
    dry_run: bool = false,
    json: bool = false,
};
const PlanFile = struct {
    path: []const u8,
    content: []const u8,
    must_write: bool,
};

fn fail(message: []const u8) error{InvalidOperation} {
    std.log.err("{s}", .{message});
    return error.InvalidOperation;
}
fn eq(a: []const u8, b: []const u8) bool { return std.mem.eql(u8, a, b); }
fn output(io: Io, data: []const u8) !void { try Io.File.stdout().writeStreamingAll(io, data); }
fn print(io: Io, a: Allocator, comptime fmt: []const u8, args: anytype) !void {
    try output(io, try std.fmt.allocPrint(a, fmt, args));
}
fn join(a: Allocator, parent: []const u8, child: []const u8) ![]const u8 {
    return std.fmt.allocPrint(a, "{s}/{s}", .{ parent, child });
}
fn validName(name: []const u8) bool {
    if (name.len == 0 or name.len > 40 or name[0] < 'a' or name[0] > 'z') return false;
    for (name) |ch| if (!((ch >= 'a' and ch <= 'z') or (ch >= '0' and ch <= '9') or ch == '-')) return false;
    return true;
}
fn safeTarget(path: []const u8) bool {
    if (!std.mem.startsWith(u8, path, "src/components/") or path.len > 180 or !std.mem.endsWith(u8, path, ".zig")) return false;
    var iterator = std.mem.splitScalar(u8, path, '/');
    while (iterator.next()) |part| {
        if (part.len == 0 or eq(part, ".") or eq(part, "..")) return false;
        for (part) |ch| if (!std.ascii.isAlphanumeric(ch) and ch != '_' and ch != '-' and ch != '.') return false;
    }
    return true;
}
fn shaHex(bytes: []const u8) [64]u8 {
    var digest: [32]u8 = undefined;
    std.crypto.hash.sha2.Sha256.hash(bytes, &digest, .{});
    const hex = "0123456789abcdef";
    var out: [64]u8 = undefined;
    for (digest, 0..) |byte, i| {
        out[i * 2] = hex[byte >> 4];
        out[i * 2 + 1] = hex[byte & 15];
    }
    return out;
}
fn correctHash(bytes: []const u8, expected: []const u8) bool {
    const actual = shaHex(bytes);
    return eq(&actual, expected);
}
fn validateRegistry(reg: Registry) !void {
    if (reg.items.len == 0 or reg.items.len > 128) return fail("Empty/oversized registry");
    for (reg.items, 0..) |item, i| {
        if (!validName(item.name) or item.files.len == 0 or item.files.len > 20) return fail("Invalid registry component");
        for (reg.items[0..i]) |earlier| if (eq(earlier.name, item.name)) return fail("Duplicate registry component");
        for (item.files) |file| {
            if (!safeTarget(file.target) or file.content.len > max_file_size or !correctHash(file.content, file.sha256)) return fail("Unsafe or corrupted bundled Zig source");
        }
        for (item.registryDependencies) |dep| if (!validName(dep)) return fail("External registry dependencies are not allowed");
    }
}
fn parseArgs(args: []const []const u8) !Options {
    var opts: Options = .{};
    var seen_command = false;
    var i: usize = 0;
    while (i < args.len) : (i += 1) {
        const arg = args[i];
        if (eq(arg, "--project") or eq(arg, "--cwd")) {
            i += 1;
            if (i >= args.len) return fail("--project needs a directory");
            opts.project = args[i];
        } else if (eq(arg, "--dry-run")) {
            opts.dry_run = true;
        } else if (eq(arg, "--json")) {
            opts.json = true;
        } else if (eq(arg, "--help") or eq(arg, "-h")) {
            opts.command = "help";
            return opts;
        } else if (std.mem.startsWith(u8, arg, "-")) {
            return fail("Unknown CLI option");
        } else if (!seen_command) {
            opts.command = arg;
            seen_command = true;
        } else {
            if (opts.count >= opts.names.len) return fail("Too many component names");
            opts.names[opts.count] = arg;
            opts.count += 1;
        }
    }
    return opts;
}
fn findItem(reg: Registry, name: []const u8) ?RegistryItem {
    for (reg.items) |item| if (eq(item.name, name)) return item;
    return null;
}
fn resolve(reg: Registry, name: []const u8, order: *std.ArrayList(RegistryItem), visiting: *std.ArrayList([]const u8), a: Allocator) !void {
    const item = findItem(reg, name) orelse return fail("Unknown component; use zevui list");
    for (order.items) |entry| if (eq(entry.name, name)) return;
    for (visiting.items) |active| if (eq(active, name)) return fail("Registry dependency cycle");
    try visiting.append(a, name);
    for (item.registryDependencies) |dep| try resolve(reg, dep, order, visiting, a);
    visiting.items.len -= 1;
    try order.append(a, item);
}
fn objGet(v: std.json.Value, key: []const u8) ?std.json.Value {
    return if (v == .object) v.object.get(key) else null;
}
fn str(v: ?std.json.Value) ?[]const u8 {
    const value = v orelse return null;
    return if (value == .string) value.string else null;
}
fn emptyObject() std.json.Value { return .{ .object = .empty }; }
fn makeLock(a: Allocator) !std.json.Value {
    var lock = emptyObject();
    try lock.object.put(a, "schema", .{ .integer = 1 });
    try lock.object.put(a, "components", emptyObject());
    return lock;
}
fn checkKind(io: Io, path: []const u8) !?Io.File.Kind {
    const stat = cwd.statFile(io, path, .{ .follow_symlinks = false }) catch |err| switch (err) {
        error.FileNotFound => return null,
        else => return err,
    };
    return stat.kind;
}
fn checkAncestors(io: Io, a: Allocator, project: []const u8, relative: []const u8) ![]const u8 {
    if (!safeTarget(relative) and !eq(relative, config_name) and !eq(relative, lock_name)) return fail("Invalid target path");
    const root_kind = try checkKind(io, project);
    if (root_kind == null or root_kind.? != .directory) return fail("Project is not a normal directory");
    var part_iter = std.mem.splitScalar(u8, relative, '/');
    var prefix: []const u8 = project;
    while (part_iter.next()) |part| {
        prefix = try join(a, prefix, part);
        const kind = try checkKind(io, prefix);
        if (kind == .sym_link) return fail("Symlink in component target; refusing write");
        if (kind != null and !eq(prefix, try join(a, project, relative)) and kind.? != .directory) return fail("Non-directory parent in target path");
    }
    return prefix;
}
fn readMaybe(io: Io, a: Allocator, path: []const u8) !?[]const u8 {
    return cwd.readFileAlloc(io, path, a, .limited(max_file_size)) catch |err| switch (err) {
        error.FileNotFound => null,
        else => return err,
    };
}
fn atomicWrite(io: Io, path: []const u8, bytes: []const u8) !void {
    var atomic = try cwd.createFileAtomic(io, path, .{ .make_path = true, .replace = true });
    defer atomic.deinit(io);
    try atomic.file.writeStreamingAll(io, bytes);
    try atomic.replace(io);
}
fn parseLock(io: Io, a: Allocator, project: []const u8) !std.json.Value {
    const path = try checkAncestors(io, a, project, lock_name);
    const data = (try readMaybe(io, a, path)) orelse return makeLock(a);
    const lock = try std.json.parseFromSliceLeaky(std.json.Value, a, data, .{});
    const schema = objGet(lock, "schema") orelse return fail("Corrupted component lock");
    if (schema != .integer or schema.integer != 1) return fail("Unsupported lock schema");
    const components = objGet(lock, "components") orelse return fail("Corrupted components lock");
    if (components != .object) return fail("Corrupted components lock");
    return lock;
}
fn recordedHash(lock: std.json.Value, name: []const u8, path: []const u8) ?[]const u8 {
    const components = objGet(lock, "components") orelse return null;
    const record = objGet(components, name) orelse return null;
    const files = objGet(record, "files") orelse return null;
    return str(objGet(files, path));
}
fn installed(lock: std.json.Value, name: []const u8) bool {
    const comps = objGet(lock, "components") orelse return false;
    return objGet(comps, name) != null;
}
fn loadProjectConfig(io: Io, a: Allocator, project: []const u8) !void {
    const path = try checkAncestors(io, a, project, config_name);
    const json = (try readMaybe(io, a, path)) orelse return fail("Run 'zevui init' first");
    const config = try std.json.parseFromSliceLeaky(std.json.Value, a, json, .{});
    if (!eq(str(objGet(config, "zig")) orelse "", "0.17.1")) return fail("Zig compatibility requires 0.17.1");
    const aliases = objGet(config, "aliases") orelse return fail("Missing aliases");
    if (!eq(str(objGet(aliases, "ui")) orelse "", "src/components")) return fail("Only src/components alias is supported in F9");
}
fn writeRecord(a: Allocator, lock: *std.json.Value, item: RegistryItem) !void {
    var record = emptyObject();
    var file_map = emptyObject();
    for (item.files) |file| try file_map.object.put(a, file.target, .{ .string = file.sha256 });
    try record.object.put(a, "version", .{ .integer = 1 });
    try record.object.put(a, "files", file_map);
    const comps = lock.object.getPtr("components") orelse return fail("Corrupted lock");
    try comps.object.put(a, item.name, record);
}
fn runInstall(io: Io, a: Allocator, opts: Options, reg: Registry) !void {
    if (opts.count == 0) return fail("Specify component names, e.g. add calendar input");
    try loadProjectConfig(io, a, opts.project);
    var lock = try parseLock(io, a, opts.project);
    var order: std.ArrayList(RegistryItem) = .empty;
    var visiting: std.ArrayList([]const u8) = .empty;
    for (opts.names[0..opts.count]) |name| try resolve(reg, name, &order, &visiting, a);
    var planned: std.ArrayList(PlanFile) = .empty;
    for (order.items) |item| {
        const present = installed(lock, item.name);
        if (eq(opts.command, "update") and !present) return fail("Cannot update a component that is not installed");
        for (item.files) |file| {
            const path = try checkAncestors(io, a, opts.project, file.target);
            const actual = try readMaybe(io, a, path);
            const expected = recordedHash(lock, item.name, file.target);
            if (expected) |old_hash| {
                if (actual == null or !correctHash(actual.?, old_hash)) return fail("Locally changed/missing Zig file; refusing overwrite");
            } else if (actual) |existing_bytes| {
                if (!correctHash(existing_bytes, file.sha256)) return fail("Unmanaged target collision; refusing overwrite");
            }
            if (eq(opts.command, "add") and expected != null and !eq(expected.?, file.sha256)) return fail("Run 'update' to replace unmodified installed sources");
            try planned.append(a, .{
                .path = file.target,
                .content = file.content,
                .must_write = actual == null or !correctHash(actual.?, file.sha256),
            });
        }
    }
    // All selected sources have been validated before the first write.
    for (planned.items) |file| {
        if (!file.must_write) continue;
        const path = try checkAncestors(io, a, opts.project, file.path);
        try print(io, a, "{s} {s}\n", .{ if (opts.dry_run) "would write" else "install", file.path });
        if (!opts.dry_run) try atomicWrite(io, path, file.content);
    }
    if (!opts.dry_run) {
        for (order.items) |item| try writeRecord(a, &lock, item);
        const path = try checkAncestors(io, a, opts.project, lock_name);
        const bytes = try std.json.Stringify.valueAlloc(a, lock, .{ .whitespace = .indent_2 });
        try atomicWrite(io, path, bytes);
    }
    try print(io, a, "{d} component(s) {s}\n", .{ order.items.len, if (opts.dry_run) "checked (dry run)" else "installed" });
}
fn runDoctor(io: Io, a: Allocator, opts: Options, reg: Registry) !void {
    try loadProjectConfig(io, a, opts.project);
    const lock = try parseLock(io, a, opts.project);
    const components = objGet(lock, "components") orelse return fail("Invalid lock");
    var errors: usize = 0;
    var it = components.object.iterator();
    while (it.next()) |entry| {
        const name = entry.key_ptr.*;
        const item = findItem(reg, name) orelse {
            try print(io, a, "{s}: unknown component\n", .{name});
            errors += 1;
            continue;
        };
        var state: []const u8 = "clean";
        for (item.files) |file| {
            const path = try checkAncestors(io, a, opts.project, file.target);
            const bytes = try readMaybe(io, a, path);
            const original = recordedHash(lock, name, file.target);
            if (bytes == null or original == null or !correctHash(bytes.?, original.?)) {
                state = "modified/missing";
                break;
            }
            if (!eq(original.?, file.sha256)) state = "update available";
        }
        try print(io, a, "{s}: {s}\n", .{ name, state });
        if (eq(state, "modified/missing")) errors += 1;
    }
    if (errors > 0) return fail("Doctor found invalid/modified files");
}
const help =
    \\Zevui Components — native Zig 0.17.1 CLI (source owned)
    \\  zevui init [--project DIR] [--dry-run]
    \\  zevui list
    \\  zevui add calendar input checkbox [--project DIR] [--dry-run]
    \\  zevui update calendar [--project DIR] [--dry-run]
    \\  zevui doctor [--project DIR]
    \\  zevui diff [--project DIR]       (same integrity report as doctor)
    \\All Zig files are checked against SHA-256; local edits are never overwritten.
    \\
;
pub fn main(init: std.process.Init) !void {
    const a = init.arena.allocator();
    const io = init.io;
    var args_iter = init.minimal.args.iterate();
    _ = args_iter.next();
    var args: std.ArrayList([]const u8) = .empty;
    while (args_iter.next()) |arg| try args.append(a, arg);
    const opts = try parseArgs(args.items);
    if (eq(opts.command, "help")) return output(io, help);
    const reg = (try std.json.parseFromSliceLeaky(Registry, a, registry_json, .{ .ignore_unknown_fields = true }));
    try validateRegistry(reg);
    if (eq(opts.command, "list")) {
        if (opts.json) {
            const Summary = struct { id: []const u8, name: []const u8 };
            var summaries: std.ArrayList(Summary) = .empty;
            for (reg.items) |item| try summaries.append(a, .{ .id = item.name, .name = item.title });
            try output(io, try std.json.Stringify.valueAlloc(a, summaries.items, .{}));
            try output(io, "\n");
        } else {
            for (reg.items) |item| try print(io, a, "{s}\t{s}\n", .{ item.name, item.title });
        }
        return;
    }
    if (eq(opts.command, "init")) {
        const build = try join(a, opts.project, "build.zig");
        if ((try checkKind(io, build)) != .file) return fail("Missing build.zig in --project directory. Create a Zig project with Zevui Initializr first; zevui init only configures components.");
        const dest = try checkAncestors(io, a, opts.project, config_name);
        if ((try checkKind(io, dest)) != null) return fail("Project already initialized; preserving existing config");
        const contents = "{\n  \"schema\": 1,\n  \"zig\": \"0.17.1\",\n  \"registry\": \"@zevui/cli:bundled\",\n  \"aliases\": { \"ui\": \"src/components\" }\n}\n";
        if (!opts.dry_run) try atomicWrite(io, dest, contents);
        try print(io, a, "{s} {s}\n", .{ if (opts.dry_run) "would create" else "created", config_name });
        return;
    }
    if (eq(opts.command, "add") or eq(opts.command, "update")) return runInstall(io, a, opts, reg);
    if (eq(opts.command, "doctor") or eq(opts.command, "diff")) return runDoctor(io, a, opts, reg);
    return fail("Unknown command. Run zevui --help");
}

test "reject traversal and unsanitized destinations" {
    try std.testing.expect(safeTarget("src/components/calendar.zig"));
    try std.testing.expect(!safeTarget("src/components/../../secret.zig"));
    try std.testing.expect(!safeTarget("src/components/evil\\path.zig"));
    try std.testing.expect(!safeTarget("other/main.zig"));
}
test "source registry digests and dependency resolver" {
    const a = std.testing.allocator;
    const parsed = try std.json.parseFromSlice(Registry, a, registry_json, .{ .ignore_unknown_fields = true });
    defer parsed.deinit();
    try validateRegistry(parsed.value);
    var order: std.ArrayList(RegistryItem) = .empty;
    defer order.deinit(a);
    var visiting: std.ArrayList([]const u8) = .empty;
    defer visiting.deinit(a);
    try resolve(parsed.value, "calendar", &order, &visiting, a);
    try std.testing.expectEqual(@as(usize, 1), order.items.len);
}
